  # í”„ë¡œê·¸ëž¨ íŒŒì¼ êµì²´ (data/ì™€ config.jsonì€ ë³´ì¡´)
  if [ "$upgrade" = 1 ]; then
    find "$PREFIX" -mindepth 1 -maxdepth 1 ! -name data ! -name config.json ! -name '*.log' -exec rm -rf {} +
  fi
