    info "ê¸°ì¡´ config.json ìœ ì§€ (ìƒˆ ê¸°ë³¸ ì„¤ì •ì€ config.json.new ì°¸ê³ )"
  fi
  cp -a "$tmp/." "$PREFIX/"
