    echo "  ì—ì´ì „íŠ¸ ì¶”ê°€: ê° ì„œë²„ì—ì„œ ì•„ëž˜ì²˜ëŸ¼ ì„¤ì¹˜í•˜ë©´ ì´ ë§ˆìŠ¤í„°ì— ìžë™ ë“±ë¡ë©ë‹ˆë‹¤."
    echo "      sudo bash fs-agent-m-install.sh --master ${myip:-<ë§ˆìŠ¤í„°IP>}$( [ "$PORT" = 15900 ] || echo ":$PORT")"
